// Apply the signed brand assets after Render copies the numbered source files.
const fs=require('fs'),brandify=require('./37-brand.js');
for(const file of ['index.html','account.html','approve.html','pricing.html','privacy.html','terms.html','refunds.html','4-cs-privacy.html','6-cs-terms.html','5-cs-refunds.html','15-privacy.html','16-terms.html','17-refunds.html']){
 const html=fs.readFileSync(file,'utf8');
 fs.writeFileSync(file,brandify(html));
}
for(const [source,target] of [['4-34-logo-192.png','2-31-icon-192.png'],['5-35-logo-512.png','3-31-icon-512.png'],['6-36-logo-favicon.png','favicon.png']])fs.copyFileSync(source,target);
let server=fs.readFileSync('server.js','utf8');
function replaceOnce(oldText,newText){const parts=server.split(oldText);if(parts.length!==2)throw Error('Server branding anchor changed: '+oldText.slice(0,60));server=parts.join(newText)}
replaceOnce("const priceDisplay=require('./2-1-34-local-prices.js');", "const priceDisplay=require('./2-1-34-local-prices.js');\nconst brandify=require('./37-brand.js');");
replaceOnce("if(url.pathname==='/icon-192.png')return serve(res,'2-31-icon-192.png');", "if(url.pathname==='/favicon.png'||url.pathname==='/favicon.ico')return serve(res,'favicon.png');if(url.pathname==='/icon-192.png')return serve(res,'2-31-icon-192.png');");
replaceOnce('return res.end(html)}if(url.pathname.startsWith(\'/invoice/view/\'))', 'return res.end(brandify(html))}if(url.pathname.startsWith(\'/invoice/view/\'))');
fs.writeFileSync('server.js',server);

// Apply the approved JobNeatly name to every served page and browser script.
// Keep URLs, database identifiers, payment IDs and existing job records unchanged.
for(const file of fs.readdirSync('.')){
 if(!/\.(html|js)$/.test(file)||file==='38-brand-build.js')continue;
 const text=fs.readFileSync(file,'utf8');
 fs.writeFileSync(file,text.replace(/ChangeSnap/g,'JobNeatly'));
}
const manifest=JSON.parse(fs.readFileSync('32-manifest.webmanifest','utf8'));
manifest.name='JobNeatly - Job paperwork and approvals';manifest.short_name='JobNeatly';
manifest.description='Keep job paperwork and approvals together';
fs.writeFileSync('32-manifest.webmanifest',JSON.stringify(manifest));
fs.writeFileSync('og.png',Buffer.from('','base64'));
